#include "simulator.h"
#include <stdlib.h>
#include <string.h>
#include <math.h>
static uint64_t rng_next(uint64_t*x){*x^=*x>>12;*x^=*x<<25;*x^=*x>>27;return *x*2685821657736338717ULL;} static double rnd(uint64_t*s){double u1=((rng_next(s)>>11)+1.0)/9007199254740993.0,u2=((rng_next(s)>>11)+1.0)/9007199254740993.0;return sqrt(-2*log(u1))*cos(6.283185307179586*u2);}
static const Segment route[]={ {10,1,0},{15,0,0},{15,0,.1},{20,0,0},{15,0,-.1},{15,0,0},{10,-1,0},{10,0,.1} }; static const TimeWindow drops[]={{45,55},{68,73}};
SimulatorConfig simulator_default_config(void){return (SimulatorConfig){.dt_s=.1,.gps_period_s=1,.gps_noise_std_m=5,.initial_speed_mps=5,.seed=42};} const Segment*simulator_default_route(size_t*n){if(n)*n=sizeof route/sizeof*route;return route;} const TimeWindow*simulator_default_dropouts(size_t*n){if(n)*n=2;return drops;} bool is_in_windows(double t,const TimeWindow*w,size_t n){for(size_t i=0;i<n;i++)if(t>=w[i].start_s&&t<=w[i].end_s)return true;return false;}
static int grow(void**p,size_t*cap,size_t need,size_t sz){if(need<=*cap)return 0;size_t nc=*cap?*cap*2:128;while(nc<need)nc*=2;void*q=realloc(*p,nc*sz);if(!q)return -1;*p=q;*cap=nc;return 0;}
int simulator_run(const SimulatorConfig*c,const Segment*r,size_t rn,SimulationResult*out){if(!c||!r||!out||rn==0||c->dt_s<=0||c->gps_period_s<c->dt_s||c->gps_noise_std_m<0||c->initial_speed_mps<0)return -1;*out=(SimulationResult){.dt=c->dt_s};if(c->dropout_count){out->dropouts=malloc(c->dropout_count*sizeof*out->dropouts);if(!out->dropouts)return -1;memcpy(out->dropouts,c->dropouts,c->dropout_count*sizeof*out->dropouts);out->dropout_count=c->dropout_count;}long ge=lround(c->gps_period_s/c->dt_s);if(ge<1)ge=1;Point2D p=c->initial_position;double speed=c->initial_speed_mps,h=c->initial_heading_rad;uint64_t seed=c->seed?c->seed:42;size_t step=0;
#define REC() do { double t=step*c->dt_s; if(grow((void**)&out->truth,&out->truth_capacity,out->truth_count+1,sizeof*out->truth))goto fail; out->truth[out->truth_count++]=(TruthSample){step,t,p,{speed*cos(h),speed*sin(h)}}; if(step%(size_t)ge==0){if(grow((void**)&out->gps,&out->gps_capacity,out->gps_count+1,sizeof*out->gps))goto fail; bool valid=!is_in_windows(t,out->dropouts,out->dropout_count); GpsMeasurement g={step,t,valid,{p.x,p.y}};if(valid&&c->gps_noise_std_m>0){g.pos.x+=rnd(&seed)*c->gps_noise_std_m;g.pos.y+=rnd(&seed)*c->gps_noise_std_m;}out->gps[out->gps_count++]=g;} } while(0)
REC();for(size_t si=0;si<rn;si++){if(r[si].duration_s<0)goto fail;long n=lround(r[si].duration_s/c->dt_s);for(long i=0;i<n;i++){speed=fmax(0,speed+r[si].accel_mps2*c->dt_s);h+=r[si].yaw_rate_rad_s*c->dt_s;p.x+=speed*cos(h)*c->dt_s;p.y+=speed*sin(h)*c->dt_s;step++;REC();}}return 0;fail:simulation_result_free(out);return -1;}
